import{_ as e,H as d,f as o,i as r}from"./chunks/framework.CBmkDW73.js";const m=JSON.parse('{"title":"명세 리뷰어 게이트 (Spec Reviewers)","description":"","frontmatter":{},"headers":[],"relativePath":"ko/skills/reviewers.md","filePath":"ko/skills/reviewers.md"}'),c={name:"ko/skills/reviewers.md"};function a(s,t,i,n,l,p){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="명세-리뷰어-게이트-spec-reviewers" tabindex="-1">명세 리뷰어 게이트 (Spec Reviewers) <a class="header-anchor" href="#명세-리뷰어-게이트-spec-reviewers" aria-label="Permalink to &quot;명세 리뷰어 게이트 (Spec Reviewers)&quot;">​</a></h1><p>명세 리뷰어 프로토콜(<code>skills/references/reviewers.md</code>)은 <code>design</code> 단계에서 스테이징 명세서를 디스크에 작성한 후 <code>plan</code>으로 전달하기 전에 실행되는 병렬 리뷰 게이트를 규정합니다.</p><h2 id="트리거-기반-동적-선택" tabindex="-1">트리거 기반 동적 선택 <a class="header-anchor" href="#트리거-기반-동적-선택" aria-label="Permalink to &quot;트리거 기반 동적 선택&quot;">​</a></h2><p>명세서 조건에 일치하는 모든 리뷰어를 실행합니다. 조건은 누적되며, 기준선 트리거 1만 일치하면 <code>spec-compliance</code>만 실행됩니다.</p><table tabindex="0"><thead><tr><th>#</th><th>트리거 조건</th><th>실행되는 리뷰어</th><th>모델 티어</th><th>검토 역할</th></tr></thead><tbody><tr><td>1</td><td><strong>항상</strong> (기준선)</td><td><code>spec-compliance</code></td><td><code>balanced</code></td><td>모든 <code>contract:</code>/<code>invariant:</code>에 대응하는 수용 <code>test:</code>가 있고, 실패 모드·범위 경계·데이터 형태가 구체적인지 검증.</td></tr><tr><td>2</td><td><strong>≥3개의 상태 열거 또는 상태 머신</strong> 정의</td><td><code>state-machine</code></td><td><code>strongest</code></td><td>합법적인 모든 상태 전이를 나열하고, 누락된 간선, 데드/도달 불가 상태, 미선언 초기/종료 상태 지적.</td></tr><tr><td>3</td><td><strong>동일 동작을 상호 참조하는 ≥2개 규칙</strong> 포함</td><td><code>consistency</code></td><td><code>strongest</code></td><td>모순, 우선순위 미정의, 불완전한 예외 목록, 본문과 표의 불일치 탐지.</td></tr><tr><td>4</td><td><strong><code>topology=multi-module</code> 또는 공유 계약 선언</strong></td><td><code>boundary</code></td><td><code>balanced</code></td><td>공유 계약의 단일 소유자, 명시적 버전 규칙, 직렬화 호환성, 모듈 간 가정 검증.</td></tr><tr><td>5</td><td><strong>영구 쓰기, 외부 부수 효과, 커밋 의미론</strong> 포함</td><td><code>safety</code></td><td><code>strongest</code></td><td>모든 쓰기 경로를 추적해 크래시 복구 누락, 중복 쓰기, 부분 커밋, 원자성 경계 검증.</td></tr><tr><td>6</td><td><strong><code>scope=complex</code> 또는 서브에이전트 병렬 구현 예정</strong></td><td><code>implementability</code></td><td><code>balanced</code></td><td>처음 보는 구현자 관점에서 미정의 자료구조, 모호한 순서, 오류 처리·기본값 누락 지적.</td></tr></tbody></table><p>모델 티어 해결 순서: 프로젝트 <code>.praxis/model-tiers.yaml</code> → 사용자 <code>~/.praxis/model-tiers.yaml</code> → 하네스 기본 모델 (<code>tiers.&lt;tier&gt;.model</code> 참조).</p><h2 id="병렬-실행-및-coordinator-통합-평가" tabindex="-1">병렬 실행 및 Coordinator 통합 평가 <a class="header-anchor" href="#병렬-실행-및-coordinator-통합-평가" aria-label="Permalink to &quot;병렬 실행 및 Coordinator 통합 평가&quot;">​</a></h2><ol><li><strong>병렬 실행</strong>: 트리거된 모든 리뷰어는 독립적인 서브에이전트로 명세서 경로(<code>docs/staging/specs/YYYY-MM-DD-&lt;topic&gt;.md</code>)만 전달받아 한 줄에 하나씩(<code>BLOCK | GAP | CONFLICT</code>) 반환합니다.</li><li><strong>Coordinator 통합 평가</strong>: 한 번만 실행됩니다. 주 에이전트가 지적 사항을 비판적으로 평가하고 충돌 해결, 누락 보완, 심각도 판정(<code>BLOCK</code> 또는 사유를 포함한 <code>DEFER</code>)을 수행해 한 번의 패스로 명세서를 수정하고 사용자에게 보고합니다. 리뷰어는 조언하고 Coordinator가 최종 결정을 내립니다.</li></ol>',8)])])}const g=e(c,[["render",a]]);export{m as __pageData,g as default};
